// ANCHOR: example
//! Expose Rust functions and types to C with a header generated by cbindgen.
//!
//! This file is also the package's C-ABI library target. The build script
//! reads its public declarations and writes bindings.h to Cargo's OUT_DIR.

/// Adds two numbers; callable from C.
#[unsafe(no_mangle)]
pub extern "C" fn add(a: i32, b: i32) -> i32 {
    a + b
}

/// Subtracts b from a; callable from C.
#[unsafe(no_mangle)]
pub extern "C" fn subtract(a: i32, b: i32) -> i32 {
    a - b
}

/// A point with the memory layout of a C struct.
#[repr(C)]
pub struct Point {
    /// The x coordinate.
    pub x: f64,
    /// The y coordinate.
    pub y: f64,
}

/// Creates a point; callable from C.
#[unsafe(no_mangle)]
pub extern "C" fn create_point(x: f64, y: f64) -> Point {
    Point { x, y }
}

/// Checks the exported functions and reports where Cargo wrote the C header.
fn main() {
    assert_eq!(add(20, 22), 42);
    assert_eq!(subtract(44, 2), 42);
    let header = std::path::Path::new(env!("OUT_DIR")).join("bindings.h");
    println!("Generated C header: {}", header.display());
}
// ANCHOR_END: example

pub fn run() {
    main();
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Exposes callable C-ABI functions and generates their header.
    /// Runs the cbindgen example through its entry point.
    #[test]
    fn test_cbindgen_example_entry_point() {
        main();
    }
}
